"""patch_unify_marking.py — UNIFY-V1 (2026-07-03 soir).

One marking flow everywhere. Three entries now route into the same
pending/confirm system (drag + loupe + 0.1px arrows + before->after delta):
  1. ✎ (Edit pixel) in the LM list: no more modal — the canvas centers on
     the marker (if off-view) and it enters pending edit mode directly.
  2. +Add -> "Place on Image": arms the press-and-drag flow (2nd-source /
     new auto-detected) instead of opening the modal.
  3. NEW — RIGHT-CLICK anywhere on the frame: name box at the cursor
     (autocomplete: unmarked existing LMs = 2nd sources first), Enter =
     pending marker AT the clicked spot, refine with arrows/drag, Enter.
The old pxe modal survives only as a fallback (unmarked LM on another cam).

Live-tested headless: all three entries, isNew resolution, zero JS errors.
Requires patch_edit_mode.py. Idempotent. Backup: .bak_unify. Hard refresh.
"""
import shutil, sys
P = 'tools/calib.html'
s = open(P).read()
if 'UNIFY-V1' in s:
    print('deja patche'); sys.exit(0)
assert 'EDIT-MODE-V1' in s, 'prerequis: patch_edit_mode.py d abord'
shutil.copy(P, P + '.bak_unify')
i = s.rindex('</body>')
s = s[:i] + '\n<script>\n// ══ [UNIFY-V1] one marking flow to rule them all ══\n// The pxe modal (✎), the +Add "Place on Image" path and a brand-new\n// RIGHT-CLICK all route into the same pending flow (drag + loupe + arrows +\n// confirm/revert). The modal only survives as a fallback for edge cases.\n(() => {\n  const addBox = document.getElementById(\'mk-add-box\');\n  const addInput = document.getElementById(\'mk-add-input\');\n\n  // lm list cache for isNew resolution (shares the datalist with \'A\')\n  let _lms = null;\n  async function ensureLms() {\n    if (_lms) return _lms;\n    try { _lms = (await fetch(\'/api/all_landmarks\').then(r => r.json())).landmarks || []; }\n    catch (_) { _lms = []; }\n    const dl = document.getElementById(\'mk-add-list\');\n    if (dl && !dl.children.length) {\n      const markedHere = new Set((projections || []).filter(p => p.marked_pixel).map(p => p.name));\n      for (const n of _lms) {\n        if (markedHere.has(n)) continue;\n        const o = document.createElement(\'option\');\n        o.value = n; dl.appendChild(o);\n      }\n    }\n    return _lms;\n  }\n\n  function centerOnImgPt(ix, iy) {\n    const [cx, cy] = toCanvas(ix, iy);\n    const r = getMainPaneRect();\n    const dx = r.width / 2 - cx, dy = r.height / 2 - cy;\n    if (Math.abs(dx) > r.width * 0.35 || Math.abs(dy) > r.height * 0.35) {\n      mainPanX += dx; mainPanY += dy;\n      draw();\n    }\n  }\n\n  // ── ✎ Edit pixel: straight to pending on the canvas ──\n  const _origOpenPx = openPxEditor;\n  openPxEditor = function(cam, lmName) {\n    if (cam === currentCam && window._mkEnterPending) {\n      const p = (projections || []).find(x => x.name === lmName);\n      if (p && p.marked_pixel) {\n        centerOnImgPt(p.marked_pixel[0], p.marked_pixel[1]);\n        window._mkEnterPending({ kind: \'move\', lm: lmName,\n          px: p.marked_pixel.slice(), orig: p.marked_pixel.slice(), isNew: false });\n        return;\n      }\n    }\n    _origOpenPx(cam, lmName);   // fallback (unmarked / other cam)\n  };\n\n  // ── +Add "Place on Image": arm the drag flow instead of the modal ──\n  const _origStartAdd = startAddPixel;\n  startAddPixel = async function() {\n    if (!addPxSelectedLm) return;\n    document.getElementById(\'add-px-modal\').style.display = \'none\';\n    const lms = await ensureLms();\n    window._mkAddIsNew = !lms.includes(addPxSelectedLm);\n    addPxMode = true;\n    canvasWrap.style.cursor = \'crosshair\';\n    const t = document.getElementById(\'tri-toast\');\n    if (t) {\n      document.getElementById(\'tri-toast-title\').textContent = \'Marking armed: \' + addPxSelectedLm + (window._mkAddIsNew ? \' (new)\' : \' (2nd source)\');\n      document.getElementById(\'tri-toast-meta\').textContent = \'Press & drag on the frame · release = review · Enter = save\';\n      t.style.display = \'block\';\n      setTimeout(() => { t.style.display = \'none\'; }, 4000);\n    }\n  };\n\n  // ── RIGHT-CLICK anywhere: add a marking right there ──\n  window._mkRcPx = null;\n  canvasWrap.addEventListener(\'contextmenu\', async e => {\n    if (e.target.closest && e.target.closest(\'#pane-2, #trace-pop, #mesh-ctrl-pop\')) return;\n    if (window._mkPending || (window._mk && window._mk.drag)) return;\n    e.preventDefault();\n    const rect = getMainPaneRect();\n    window._mkRcPx = canvasToImg(e.clientX - rect.left, e.clientY - rect.top);\n    await ensureLms();\n    addBox.style.left = Math.min(window.innerWidth - 300, e.clientX + 8) + \'px\';\n    addBox.style.top = Math.max(10, e.clientY - 56) + \'px\';\n    addBox.style.display = \'block\';\n    addInput.value = \'\';\n    addInput.focus();\n  });\n\n  // Enter dans la boite APRES un right-click: pending direct a la position\n  addInput.addEventListener(\'keydown\', async e => {\n    if (e.key === \'Escape\') { window._mkRcPx = null; return; }\n    if (e.key !== \'Enter\' || !window._mkRcPx) return;\n    const name = addInput.value.trim();\n    if (!name) return;\n    e.stopImmediatePropagation(); e.preventDefault();\n    addBox.style.display = \'none\';\n    const lms = await ensureLms();\n    const px = window._mkRcPx;\n    window._mkRcPx = null;\n    addPxSelectedLm = name;\n    window._mkEnterPending({ kind: \'place\', lm: name, px: [px[0], px[1]],\n                             orig: null, isNew: !lms.includes(name) });\n  }, true);\n\n  console.log(\'[UNIFY-V1] unified marking entries active\');\n})();\n</script>\n' + s[i:]
open(P, 'w').write(s)
print('UNIFY-V1 applique. Hard refresh (pas besoin de redemarrer le serveur).')
